    <h2 class="section-title" style="text-align:center;margin-bottom:40px;">More reasons to join</h2>
    <div class="features-grid">
      <div class="feature-card">
        <h3>Enjoy on your TV</h3>
        <p>Watch on smart TVs, PlayStation, Xbox, Chromecast, Apple TV, Blu-ray players and more.</p>
        <svg class="feature-icon" viewBox="0 0 24 24" fill="currentColor"><rect x="2" y="3" width="20" height="14" rx="2" stroke="currentColor" stroke-width="2" fill="none"/><polyline points="8,21 12,17 16,21" stroke="currentColor" stroke-width="2" fill="none"/></svg>
